<script setup lang="ts">
import { ref } from 'vue'
interface AdminUser { id: string; display_name: string | null; role: string; status: string; created_at: string }
const page = ref(1)
const { data, refresh, pending, error: loadError } = await useFetch<{ items: AdminUser[]; per_page: number }>('/api/admin', { query: computed(() => ({ section: 'users', page: page.value })) })
useListNavigation(page, pending, '.admin-table-wrap')
const error = ref('')
const busy = ref<string | null>(null)
const failedUser = ref<string | null>(null)
const update = async (user: AdminUser) => { if (busy.value) return; const status = user.status === 'active' ? 'suspended' : 'active'; if (!window.confirm(`${status === 'suspended' ? 'Tangguhkan' : 'Aktifkan'} akun ini?`)) return; busy.value = user.id; error.value = ''; failedUser.value = null; try { await $fetch(`/api/admin/users/${user.id}`, { method: 'PATCH', body: { status } }); await refresh() } catch (e: unknown) { failedUser.value = user.id; error.value = requestMessage(e) } finally { busy.value = null } }
function requestMessage(error: unknown) { if (error && typeof error === 'object' && 'data' in error && error.data && typeof error.data === 'object' && 'statusMessage' in error.data && typeof error.data.statusMessage === 'string') return error.data.statusMessage; return 'Status pengguna tidak berubah.' }
</script>
<template><section class="admin-content"><header class="page-heading"><h1>Pengguna</h1><p>Kelola akses akun. Perubahan tercatat dalam audit.</p></header><LoadError v-if="loadError" message="Daftar pengguna belum bisa dimuat." :retrying="pending" @retry="refresh()" /><p v-else-if="pending" role="status">Memuat pengguna…</p><div v-else class="admin-table-wrap" role="region" aria-label="Daftar pengguna, geser untuk melihat semua kolom" tabindex="0"><table class="admin-table"><thead><tr><th>Nama tampilan</th><th>Peran</th><th>Status</th><th>Bergabung</th><th>Aksi</th></tr></thead><tbody><tr v-for="user in data?.items" :key="user.id"><td>{{ user.display_name || 'Belum diatur' }}</td><td>{{ user.role }}</td><td>{{ user.status }}</td><td>{{ new Date(user.created_at).toLocaleDateString('id-ID') }}</td><td><button v-if="user.role!=='admin'" class="button button-outline button-small" :disabled="!!busy" @click="update(user)">{{ user.status==='active'?'Tangguhkan':'Aktifkan' }}</button><span v-else>Admin</span><p v-if="error && failedUser === user.id" class="notice notice-error" role="alert">{{ error }}</p></td></tr></tbody></table></div><nav aria-label="Halaman pengguna admin" class="pagination"><button class="button button-outline button-small" :disabled="page === 1 || pending" @click="page--">Sebelumnya</button><span>Halaman {{ page }}</span><button class="button button-outline button-small" :disabled="pending || (data?.items.length ?? 0) < (data?.per_page ?? 50) || page >= 1000" @click="page++">Berikutnya</button></nav></section></template>
